//! The bionic-only C API for AOSP code built against glibc (plan S11 bridge 1 class b, M2 "bionic"):
//! glibc stays the C library; this adds what bionic has and glibc lacks, as declared by bionic's own
//! headers (C declarations and signature checks generated by atl-bridgegen, see build.rs).
//!
//! - System properties: a reader of bionic's property-area file format (`props`), the same file guest
//!   bionic maps natively. One pre-split area at `$ATL_PROP_AREA`, else bionic's `PROP_DIRNAME`
//!   (`/dev/__properties__`, where the sandbox will put it). `__system_property_set` fails with
//!   `ENOENT` until atld's property service exists. `image` builds area files.
//! - `android_get_device_api_level` (`ro.build.version.sdk`), the application target SDK and its setter.
//! - libasync_safe's no-allocation formatting and logging (`async_safe`): what AOSP code built here calls.
//! - fdsan's error level (`fdsan`); glibc checks no descriptor owner, so it never reports.
//!
//! - `android_dlopen_ext` (`dlext`: the extended flags taken) and `android_get_exported_namespace`, both
//!   through `linker`, the one place namespaced loads go (one namespace here).
//! - `android_mallopt`: no bionic allocator option exists on glibc; each is refused as bionic refuses
//!   one it lacks.
//!
//! Built as one shared library per process (cargo-c), so one store and one target SDK. Boundary crate:
//! `unsafe` only in `ffi` (the C ABI shells), `map` (the shared mapping) and `linker` (`dlopen`); they
//! call safe code.
#![deny(unsafe_code)]

/// Generated by build.rs from bionic's pinned sources.
mod generated {
    pub mod system_properties {
        include!(concat!(env!("OUT_DIR"), "/system_properties.rs"));
    }
    pub mod api_level {
        include!(concat!(env!("OUT_DIR"), "/api_level.rs"));
    }
    pub mod libdl_android {
        include!(concat!(env!("OUT_DIR"), "/libdl_android.rs"));
    }
    pub mod async_safe {
        include!(concat!(env!("OUT_DIR"), "/async_safe.rs"));
    }
    pub mod fdsan {
        include!(concat!(env!("OUT_DIR"), "/fdsan.rs"));
    }
    pub mod dlext {
        include!(concat!(env!("OUT_DIR"), "/dlext.rs"));
    }
    pub mod malloc {
        include!(concat!(env!("OUT_DIR"), "/malloc.rs"));
    }
    /// bionic's property-area format: record layouts and constants.
    pub mod prop_format {
        include!(concat!(env!("OUT_DIR"), "/prop_area.rs"));
    }
}

pub mod async_safe;
pub mod dlext;
pub mod fdsan;
#[allow(unsafe_code)]
mod ffi;
pub mod image;
#[allow(unsafe_code)]
mod linker;
#[allow(unsafe_code)]
mod map;
pub mod props;
pub mod sdk;
